class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long pow(long b, long e) {
    long r = 1;
    for (b %= MOD; e > 0; e >>= 1) {
      if ((e & 1) == 1) r = r * b % MOD;
      b = b * b % MOD;
    }
    return r;
  }

  public int distanceSum(int m, int n, int k) {
    long total = 0;
    for (long d = 1; d < m; d++) total = (total + d * (m - d) % MOD * n % MOD * n) % MOD;
    for (long d = 1; d < n; d++) total = (total + d * (n - d) % MOD * m % MOD * m) % MOD;
    int N = m * n - 2, K = k - 2;
    long num = 1, den = 1;
    for (int i = 1; i <= K; i++) {
      num = num * (N - K + i) % MOD;
      den = den * i % MOD;
    }
    return (int) (total * (num * pow(den, MOD - 2) % MOD) % MOD);
  }
}
